/* From Uiverse.io by gharsh11032000 - Tags: apple, switch, checkbox, toggle, toggle switch */
/* The switch - the box around the slider */
.__UIV_SCOPE__ .switch {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 3.5em;
  height: 2em;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

/* The slider */
.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  inset: 0;
  background: #9fccfa;
  border-radius: 50px;
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.__UIV_SCOPE__ .slider:before {
  position: absolute;
  content: "";
  display: flex;
  align-items: center;
  justify-content: center;
  height: 2em;
  width: 2em;
  inset: 0;
  background-color: white;
  border-radius: 50px;
  box-shadow: 0 10px 20px rgba(0,0,0,0.4);
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.__UIV_SCOPE__ .switch input:checked + .slider {
  background: #0974f1;
}

.__UIV_SCOPE__ .switch input:focus + .slider {
  box-shadow: 0 0 1px #0974f1;
}

.__UIV_SCOPE__ .switch input:checked + .slider:before {
  transform: translateX(1.6em);
}
